<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$action=(string)($_POST['action']??'dispatch');if($action==='webhook'){$events=array_values(array_filter(array_map('trim',preg_split('/[,\s]+/',(string)($_POST['events']??'*'))?:[])));$created=$delivery->createWebhook(trim((string)$_POST['url']),$events,(int)$admin['id']);$message='<div class="alert success">Webhook utworzony. Secret (pokażemy tylko teraz): <code>'.Web::e($created['secret']).'</code></div>';}elseif($action==='dispatch'){$r=$delivery->dispatch(100);$m=$mail->dispatch(100);$message='<pre class="code">'.Web::e(json_encode(['events'=>$r,'mail'=>$m],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>';}elseif($action==='alert'){$destination=trim((string)$_POST['destination']);$channel=(string)$_POST['channel'];if(!in_array($channel,['email','webhook','both'],true))throw new RuntimeException('invalid_channel');$db->execute('INSERT INTO alert_rules(name,event_type,minimum_severity,channel,destination,created_by) VALUES(?,?,?,?,?,?)',[trim((string)$_POST['name']),trim((string)$_POST['event_type']),$_POST['minimum_severity'],$channel,$destination,(int)$admin['id']]);$message='<div class="alert success">Reguła alertu dodana.</div>';}}catch(Throwable $e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$hooks='';foreach($db->all('SELECT id,url,events_json,enabled,last_success_at,last_failure_at FROM webhooks ORDER BY id DESC') as $h)$hooks.='<tr><td>'.(int)$h['id'].'</td><td>'.Web::e($h['url']).'</td><td>'.Web::e($h['events_json']).'</td><td>'.((bool)$h['enabled']?'Tak':'Nie').'</td><td>'.Web::e($h['last_success_at']?:'—').'</td><td>'.Web::e($h['last_failure_at']?:'—').'</td></tr>';Web::page('Deliveries','<div class="page-head"><div><h1>Webhooks / Alerting / SIEM</h1><p>Podpisane webhooki, retry queue, alerty i syslog.</p></div></div>'.$message.'<section class="card"><h2>Nowy webhook</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>HTTPS URL<input type="url" name="url" required></label><label>Zdarzenia<input name="events" value="*"></label><button name="action" value="webhook">Dodaj</button></form></section><section class="card"><h2>Reguła alertu</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Nazwa<input name="name" required></label><label>Zdarzenie<input name="event_type" value="*" required></label><label>Severity<select name="minimum_severity"><option>info</option><option selected>warning</option><option>high</option><option>critical</option></select></label><label>Kanał<select name="channel"><option>email</option><option>webhook</option><option>both</option></select></label><label>Adres/URL<input name="destination" required></label><button name="action" value="alert">Dodaj</button></form></section><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><button class="primary" name="action" value="dispatch">Uruchom delivery queue</button></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>URL</th><th>Events</th><th>Aktywny</th><th>Success</th><th>Failure</th></tr></thead><tbody>'.$hooks.'</tbody></table></div>',$admin);
